document.addEventListener("DOMContentLoaded",function(){var s=requireLogin("student");if(!s)return;var p=findStudentByUsername(s.username);if(!p)return;var f={"profile-name":p.name,"profile-id":p.studentId,"profile-email":p.email,"profile-dept":p.department,"profile-username":p.username};for(var k in f){var e=document.getElementById(k);if(e)e.textContent=f[k]||"—";}var e=document.getElementById("profile-enrolled");if(e)e.textContent=getEnrolledCourseCodes(s.username).length;var c=document.getElementById("profile-completed");if(c)c.textContent=getCompletedCourseCountForStudent(s.username);});
